import { useState, useEffect, useRef } from "react";
import usePlayers from "../../hooks/usePlayers";
import useRules from "../../hooks/fetchRules";
import "../melding/meldStyles.css";
import { db } from "../../firebaseConfig";
import { ref, onValue, set, off } from "firebase/database";

const StyringsBot = () => {
  const players = usePlayers();
  const rules = useRules();

  // Local state for form fields
  const [brutt, setBrutt] = useState([]);
  const [melder, setMelder] = useState("");
  const [datoBrudd, setDatoBrudd] = useState("");
  const [paragraf, setParagraf] = useState("");
  const [beskrivelse, setBeskrivelse] = useState("");
  const [enheter, setEnheter] = useState(1);
  const [id, setId] = useState(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitCooldown, setSubmitCooldown] = useState(false);
  const submitButtonRef = useRef(null);
  const [gullPaGulv, setGullPaGulv] = useState(false);
  const [selectedTime, setSelectedTime] = useState("");
  const [selectedBrutt, setSelectedBrutt] = useState("");

  useEffect(() => {
    setGullPaGulv(paragraf.includes("Gull på gulv"));
  }, [paragraf]);

  useEffect(() => {
    if (submitCooldown) {
      if (submitButtonRef.current) submitButtonRef.current.disabled = true;
      const timer = setTimeout(() => {
        setSubmitCooldown(false);
        if (submitButtonRef.current) submitButtonRef.current.disabled = false;
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [submitCooldown]);

  // Fetch the next available ID from the database
  useEffect(() => {
    const dbRef = ref(db, "boter");
    const handleDataChange = (snapshot) => {
      if (snapshot.exists()) {
        setId(Object.keys(snapshot.val()).length);
      }
    };
    onValue(dbRef, handleDataChange);
    return () => off(dbRef, handleDataChange);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isSubmitting || submitCooldown) return;

    setIsSubmitting(true);
    setSubmitCooldown(true);

    const finalDescription =
      gullPaGulv && selectedTime
        ? `${selectedTime} - ${beskrivelse}`
        : beskrivelse;

    const bot = {
      brutt,
      melder,
      datoBrudd,
      paragraf,
      dato: new Date().toDateString(),
      beskrivelse: finalDescription,
      enheter,
      id,
    };

    try {
      await set(ref(db, `boter/${id}`), bot);
      window.location.href = "/done";
    } catch (error) {
      console.error("Failed to submit data", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleBruttSelectChange = (e) => {
    const newBrutt = e.target.value;
    setBrutt([...brutt, newBrutt]);
    setSelectedBrutt("");
  };

  const handleRemoveBrutt = (playerToRemove) => {
    setBrutt(brutt.filter((player) => player !== playerToRemove));
  };

  return (
    <>
      <form id="mform" onSubmit={handleSubmit}>
        <div id="formDiv">
          <label>
            Hvem har brutt loven?
            <br />
            <select
              value={selectedBrutt}
              onChange={handleBruttSelectChange}
              required={brutt.length === 0}
            >
              <option value="" disabled>
                Velg spiller
              </option>
              {players
                .filter((p) => !brutt.includes(p))
                .map((p) => (
                  <option key={p} value={p}>
                    {p}
                  </option>
                ))}
            </select>
          </label>
          {brutt.map((selectedPlayer) => (
            <span key={selectedPlayer}>
              {selectedPlayer}
              <button
                className="remove_button"
                type="button"
                onClick={() => handleRemoveBrutt(selectedPlayer)}
              >
                fjern
              </button>
              <br />
            </span>
          ))}

          <br />
          <label>
            Hvem er du?
            <br />
            <select
              value={melder}
              onChange={(e) => setMelder(e.target.value)}
              required
            >
              <option value="" disabled>
                Velg spiller
              </option>
              {players.map((p) => (
                <option key={p} value={p}>
                  {p}
                </option>
              ))}
            </select>
          </label>
          <br />
          <label>
            Når skjedde lovbruddet
            <br />
            <input
              type="date"
              onChange={(e) => setDatoBrudd(e.target.value)}
              value={datoBrudd}
            ></input>
          </label>
          <br />
          <label>
            Hvilken paragraf er brudt?
            <br />
            <select
              value={paragraf}
              onChange={(e) => setParagraf(e.target.value)}
              required
            >
              <option value="" disabled>
                Select a rule
              </option>
              {rules.map((r) => (
                <option key={r} value={r}>
                  {r}
                </option>
              ))}
            </select>
          </label>
          <br />
          {gullPaGulv && (
            <>
              <label>
                Tidspunkt for hendelsen:
                <br />
                <input
                  type="time"
                  value={selectedTime}
                  onChange={(e) => setSelectedTime(e.target.value)}
                  required
                />
              </label>
            </>
          )}

          <br />
          <label>
            Beskrivelse av situasjonen:
            <br />
            <textarea
              value={beskrivelse}
              onChange={(e) => setBeskrivelse(e.target.value)}
              rows="5"
              cols="50"
              placeholder="Beskriv hendelsen her..."
              required
            ></textarea>
          </label>

          <br />
          <label>
            Antall enheter:
            <br />
            <input
              id="antall_enheter"
              type="number"
              value={enheter}
              inputmode="numeric"
              pattern="[0-9]*"
              onChange={(e) => setEnheter(Number(e.target.value))}
              min={1}
              max={30}
              required
            />
          </label>
          <br />
          <button
            ref={submitButtonRef}
            type="submit"
            disabled={isSubmitting || submitCooldown}
          >
            {submitCooldown ? "Sender inn..." : "Meld bot"}
          </button>
          {submitCooldown && <p>Sender inn</p>}
        </div>
      </form>
    </>
  );
};

export default StyringsBot;
